import json
import base64
from StellarUploadImage import lambda_handler

def create_sample_image_data():
    """Create a small sample PNG image data in base64 format for testing"""
    # This is a tiny 1x1 pixel PNG image in base64
    # PNG signature + IHDR + IDAT + IEND chunks for a 1x1 transparent pixel
    tiny_png_base64 = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChAI9jU77kgAAAABJRU5ErkJggg=="
    return tiny_png_base64

def test_direct_json_event():
    """Test with direct JSON event containing image data"""
    print("\n=== Testing Direct JSON Event ===")
    
    # Create event with base64 image data
    event = {
        'image_data': create_sample_image_data(),
        'file_extension': '.png',
        'custom_name': 'test_image_001',
        'folder': 'test_products',
        'make_public': True
    }
    
    context = {}
    
    try:
        response = lambda_handler(event, context)
        print("Direct JSON Response:")
        print(json.dumps(response, indent=2))
        return response
    except Exception as e:
        print(f"Direct JSON Error: {e}")
        return None

