def test_different_file_extensions():
    """Test with different file extensions"""
    print("\n=== Testing Different File Extensions ===")
    
    extensions = ['.png', '.jpg', '.jpeg', '.gif', '.webp']
    
    for ext in extensions:
        print(f"\nTesting {ext} extension:")
        event = {
            'image_data': create_sample_image_data(),
            'file_extension': ext,
            'custom_name': f'test_image_{ext[1:]}',
            'folder': 'test_extensions',
            'make_public': True
        }
        
        context = {}
        
        try:
            response = lambda_handler(event, context)
            print(f"{ext} Response Status: {response.get('statusCode', 'Unknown')}")
            if response.get('statusCode') == 200:
                data = json.loads(response['body']).get('data', {})
                print(f"URL: {data.get('image_url', 'No URL')}")
        except Exception as e:
            print(f"{ext} Error: {e}")

